/* DFD CRRO Manual: internal search engine.
 *
 * Runs entirely in the browser against assets/search-index.js (generated by build_site.py).
 * Ranking: BM25F over heading, page title, and body fields, with
 *   - light English stemming and stop words
 *   - domain synonyms and acronyms (PAT, PHS, VerifEYE, account numbers, ...)
 *   - prefix matching while typing and typo tolerance (edit distance 1-2)
 *   - exact phrases ("..."), exclusions (-word), filters (ch:9, app:g, part:recruitment)
 *   - all-terms coverage boost and a proximity bonus
 * UI: header dropdown on every page, full results page (search.html), and in-page
 * highlighting of the matched words when a result is opened.
 */
(function () {
  'use strict';

  // ───────────────────────── text processing ─────────────────────────
  const STOP = new Set(('a an and are as at be but by for from has have how i if in into is it its of on or ' +
    'our so than that the their them then there these this to was we what when where which who why will with ' +
    'you your do does did can should would could may also not no all any each per via about after before').split(' '));

  const DOUBLE = /(bb|dd|gg|mm|nn|pp|rr|tt)$/;

  function stem(w) {
    if (w.length <= 3 || /\d/.test(w)) return w;
    if (w.endsWith("'s")) w = w.slice(0, -2);
    if (w.endsWith('ies') && w.length > 4) w = w.slice(0, -3) + 'y';
    else if (/(ss|x|z|ch|sh)es$/.test(w)) w = w.slice(0, -2);
    else if (w.endsWith('s') && !/(ss|us|is|ys)$/.test(w)) w = w.slice(0, -1);
    if (w.endsWith('ing') && w.length > 5) {
      w = w.slice(0, -3);
      if (DOUBLE.test(w)) w = w.slice(0, -1);
    } else if (w.endsWith('ed') && w.length > 4) {
      w = w.slice(0, -2);
      if (DOUBLE.test(w)) w = w.slice(0, -1);
    }
    if (w.endsWith('e') && w.length > 3) w = w.slice(0, -1);
    return w;
  }

  function norm(s) {
    return s.normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase()
      .replace(/[‘’]/g, "'").replace(/[“”]/g, '"');
  }

  const WORD = /[a-z0-9]+(?:[.'\-/][a-z0-9]+)*/g;

  // Index-side tokenizer. Compound tokens (320100.7726, p-card, 9.5.4) are kept whole and
  // also split into parts and a joined form, all at the same position.
  function tokenize(text) {
    const out = [];
    const s = norm(text);
    let m, pos = 0;
    WORD.lastIndex = 0;
    while ((m = WORD.exec(s))) {
      let w = m[0].replace(/'s$/, '').replace(/'/g, '');
      if (!w) continue;
      const forms = new Set();
      if (!STOP.has(w)) forms.add(stem(w));
      if (/[.\-/]/.test(w)) {
        forms.add(w.replace(/[.\-/]/g, ''));
        for (const part of w.split(/[.\-/]/)) if (part && !STOP.has(part)) forms.add(stem(part));
      }
      for (const f of forms) out.push([f, pos]);
      pos++;
    }
    return out;
  }

  // ───────────────────────── synonyms and acronyms ─────────────────────────
  const SYNONYM_GROUPS = [
    ['pat', 'physical ability test', 'physical agility test'],
    ['phs', 'personal history statement'],
    ['verifeye', 'polygraph', 'poly', 'credibility assessment', 'converus'],
    ['psych', 'psychological', 'pepper'],
    ['medical exam', 'concentra', 'physicals'],
    ['crr', 'community risk reduction'],
    ['crro', 'crr officer', 'community risk reduction officer'],
    ['dfr', 'drone as first responder', 'drone first responder'],
    ['uas', 'drone', 'unmanned aircraft', 'suas'],
    ['dfd', 'denton fire department'],
    ['nno', 'national night out'],
    ['cfa', 'citizens fire academy'],
    ['rts', 'ready to serve', 'recruiting newsletter'],
    ['frontline report', 'crr newsletter'],
    ['jde', 'jd edwards', 'general ledger'],
    ['pcard', 'p-card', 'purchasing card'],
    ['emburse', 'certify'],
    ['civil service exam', 'written exam', 'entrance exam'],
    ['fpsi', 'fire police selection'],
    ['tcfp', 'texas commission on fire protection'],
    ['dshs', 'department of state health services'],
    ['emt', 'emergency medical technician'],
    ['ems', 'emergency medical services'],
    ['fy', 'fiscal year'],
    ['appraisal', 'program appraisal', 'quarterly report'],
    ['weekly report', 'weekly task report'],
    ['cpse', 'cfai', 'accreditation'],
    ['caas', 'ambulance accreditation'],
    ['dq', 'disqualification', 'disqualify'],
    ['ot', 'overtime'],
    ['dns', 'did not show'],
    ['bvlos', 'beyond visual line of sight'],
    ['coa', 'certificate of authorization'],
    ['explorer', 'exploring', 'scouting america', 'post 1291'],
    ['pension', 'dfrrf', 'relief and retirement'],
    ['ride along', 'ride-along', 'ridealong'],
    ['extra points', 'preference points'],
    ['clown', 'clowns on fire'],
    ['7726', 'physicals/psych', 'physicals psych'],
    ['6508', 'other account'],
    ['7826', 'diversity account', 'diversity'],
    ['7764', 'pub education', 'public education'],
    ['smoke detector', 'smoke alarm'],
    ['first arriving', 'dashboard slides', 'station dashboard'],
    ['checkbook', 'ledger'],
    ['recruit', 'recruitment'],
    ['salary', 'pay', 'compensation'],
    ['interview', 'oral board', 'panel interview'],
    ['hub', 'sharepoint'],
    ['eso', 'community events'],
  ];

  // ───────────────────────── index ─────────────────────────
  const FIELDS = ['h', 'pt', 't'];
  const FW = { h: 5, pt: 1.5, t: 1 };   // field weights
  const FB = { h: 0.5, pt: 0.3, t: 0.75 };
  const K1 = 1.2;

  let IX = null;

  function buildIndex() {
    if (IX) return IX;
    const src = window.CRRO_SEARCH_INDEX;
    if (!src) return null;
    const docs = src.docs;
    const post = new Map();                 // term -> Map(docIdx -> [tfH, tfPT, tfT])
    const lens = docs.map(() => [0, 0, 0]);
    const bodyPos = docs.map(() => new Map()); // term -> positions in body
    const searchText = [];
    const surface = new Set();
    docs.forEach((d, i) => {
      const fieldText = { h: d.h + ' ' + (d.b || []).join(' '), pt: d.pt, t: d.t };
      FIELDS.forEach((f, fi) => {
        const toks = tokenize(fieldText[f]);
        lens[i][fi] = toks.length;
        for (const [term, pos] of toks) {
          let pl = post.get(term);
          if (!pl) post.set(term, (pl = new Map()));
          let tf = pl.get(i);
          if (!tf) pl.set(i, (tf = [0, 0, 0]));
          tf[fi]++;
          if (f === 't') {
            let p = bodyPos[i].get(term);
            if (!p) bodyPos[i].set(term, (p = []));
            p.push(pos);
          }
        }
      });
      (norm(d.h + ' ' + d.t).match(WORD) || []).forEach(w => surface.add(w.replace(/'s$/, '').replace(/'/g, '')));
      searchText.push(' ' + norm(d.h + ' ' + (d.b || []).join(' ') + ' ' + d.t).replace(/[^a-z0-9]+/g, ' ') + ' ');
    });
    const avg = [0, 1, 2].map(k => lens.reduce((a, l) => a + l[k], 0) / docs.length || 1);
    const vocab = Array.from(post.keys()).sort();
    const syn = SYNONYM_GROUPS.map(g => g.map(p => tokenize(p).filter((x, j, a) => a.findIndex(y => y[1] === x[1]) === j).map(x => x[0])));
    const pages = new Map(src.pages.map(p => [p.p, p]));
    const synVocab = new Set(syn.flat(2));
    IX = { src, docs, post, lens, avg, vocab, bodyPos, searchText, syn, synVocab, pages, surface, N: docs.length };
    return IX;
  }

  function idf(term) {
    const pl = IX.post.get(term);
    const n = pl ? pl.size : 0;
    return Math.log(1 + (IX.N - n + 0.5) / (n + 0.5));
  }

  function termScore(term, i) {
    const pl = IX.post.get(term);
    if (!pl) return 0;
    const tf = pl.get(i);
    if (!tf) return 0;
    let t = 0;
    FIELDS.forEach((f, k) => {
      if (!tf[k]) return;
      t += FW[f] * tf[k] / (1 - FB[f] + FB[f] * IX.lens[i][k] / IX.avg[k]);
    });
    return idf(term) * t * (K1 + 1) / (t + K1);
  }

  // ───────────────────────── fuzzy helpers ─────────────────────────
  function editDistance(a, b, max) {
    if (Math.abs(a.length - b.length) > max) return max + 1;
    const d = [];
    for (let i = 0; i <= a.length; i++) { d[i] = [i]; }
    for (let j = 1; j <= b.length; j++) d[0][j] = j;
    for (let i = 1; i <= a.length; i++) {
      let rowMin = Infinity;
      for (let j = 1; j <= b.length; j++) {
        const c = a[i - 1] === b[j - 1] ? 0 : 1;
        let v = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + c);
        if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) v = Math.min(v, d[i - 2][j - 2] + 1);
        d[i][j] = v;
        if (v < rowMin) rowMin = v;
      }
      if (rowMin > max) return max + 1;
    }
    return d[a.length][b.length];
  }

  function prefixTerms(p, limit) {
    const v = IX.vocab;
    let lo = 0, hi = v.length;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (v[mid] < p) lo = mid + 1; else hi = mid; }
    const out = [];
    for (let k = lo; k < v.length && v[k].startsWith(p) && out.length < limit; k++) if (v[k] !== p) out.push(v[k]);
    return out;
  }

  function fuzzyTerms(t) {
    if (t.length < 4 || /^\d+$/.test(t)) return [];
    const max = t.length >= 8 ? 2 : 1;
    const out = [];
    for (const v of IX.vocab) {
      if (Math.abs(v.length - t.length) > max || v[0] !== t[0] && max === 1) continue;
      const dist = editDistance(t, v, max);
      if (dist <= max) out.push([v, dist]);
    }
    out.sort((a, b) => a[1] - b[1] || IX.post.get(b[0]).size - IX.post.get(a[0]).size);
    return out.slice(0, 4);
  }

  // ───────────────────────── query parsing ─────────────────────────
  // A query becomes clauses. Every clause holds alternatives; an alternative is a list of
  // stemmed terms that must all appear, with a weight. Phrase clauses also need an exact match.
  function parseQuery(q) {
    const res = { clauses: [], exclude: [], filters: {}, raw: q, words: [] };
    let s = norm(q);
    s = s.replace(/\b(ch|chapter|app|appendix|part):\s*([a-z0-9-]+)/g, (_, k, v) => {
      k = k.startsWith('ch') ? 'ch' : k.startsWith('app') ? 'app' : 'part';
      res.filters[k] = v; return ' ';
    });
    s = s.replace(/"([^"]+)"/g, (_, ph) => {
      const terms = tokenize(ph).filter((x, j, a) => a.findIndex(y => y[1] === x[1]) === j).map(x => x[0]);
      if (terms.length) {
        res.clauses.push({ phrase: ' ' + ph.replace(/[^a-z0-9]+/g, ' ').trim() + ' ', alts: [{ terms, w: 1.5 }], label: ph });
        res.words.push(...terms);
      }
      return ' ';
    });
    s = s.replace(/(^|\s)-([a-z0-9][^\s]*)/g, (_, sp, w) => { res.exclude.push(...tokenize(w).map(x => x[0])); return ' '; });

    const words = (s.match(WORD) || []).map(w => w.replace(/'s$/, '').replace(/'/g, '')).filter(Boolean);
    const endsWithSpace = /\s$/.test(q);
    const kept = words.filter(w => !STOP.has(w));
    const stems = kept.map(w => stem(w));

    // synonym groups that match a run of query words
    const used = new Array(stems.length).fill(false);
    const groupClauses = [];
    IX.syn.forEach((group, gi) => {
      for (const phrase of group) {
        if (!phrase.length) continue;
        for (let k = 0; k + phrase.length <= stems.length; k++) {
          if (phrase.every((t, j) => stems[k + j] === t || (kept[k + j] && kept[k + j].replace(/[.\-/]/g, '') === t))) {
            if (used.slice(k, k + phrase.length).some(Boolean)) continue;
            for (let j = 0; j < phrase.length; j++) used[k + j] = true;
            const alts = group.map(p => ({ terms: p, w: p === phrase ? 1 : 0.7 })).filter(a => a.terms.length);
            groupClauses.push({ at: k, alts, label: kept.slice(k, k + phrase.length).join(' ') });
          }
        }
      }
    });

    stems.forEach((t, k) => {
      if (used[k]) return;
      const raw = kept[k];
      const alts = [];
      if (/[.\-/]/.test(raw)) {
        const joined = raw.replace(/[.\-/]/g, '');
        if (IX.post.has(raw)) alts.push({ terms: [raw], w: 1 });
        if (IX.post.has(joined)) alts.push({ terms: [joined], w: 1 });
        if (!alts.length) alts.push({ terms: raw.split(/[.\-/]/).filter(Boolean).map(stem), w: 0.9 });
      } else {
        const typo = raw.length >= 5 && !IX.surface.has(raw);
        alts.push({ terms: [t], w: typo ? 0.45 : 1 });
        const isLast = k === stems.length - 1 && !endsWithSpace;
        if (t.length >= 2 && (isLast || !IX.post.has(t))) {
          for (const p of prefixTerms(raw, 12)) alts.push({ terms: [p], w: 0.55 * Math.min(1, raw.length / p.length + 0.2) });
        }
        // typo tolerance: the stem is unknown, or the word as typed never appears in the manual
        if (!IX.post.has(t) || (raw.length >= 5 && !IX.surface.has(raw) && !(isLast && prefixTerms(raw, 1).length))) {
          const seen = new Set(alts.map(a => a.terms[0]));
          for (const [v, dist] of fuzzyTerms(t).concat(fuzzyTerms(raw))) {
            if (seen.has(v)) continue;
            seen.add(v);
            alts.push({ terms: [v], w: (dist === 1 ? 0.6 : 0.35) * (IX.synVocab.has(v) ? 1.6 : 1), fuzzy: true });  // domain words win ties
          }
          // a misspelling usually targets the more common word
          const df = x => (IX.post.get(x) ? IX.post.get(x).size : 0);
          if (typo && alts.some(a => a.fuzzy && df(a.terms[0]) > df(t))) alts[0].w = 0.2;
        }
      }
      groupClauses.push({ at: k, alts, label: raw });
    });
    groupClauses.sort((a, b) => a.at - b.at);
    res.clauses.unshift(...groupClauses);
    res.words.push(...stems);
    return res;
  }

  // ───────────────────────── search ─────────────────────────
  function passesFilters(d, f) {
    if (f.ch) { const m = d.p.match(/^ch(\d+)/); if (!m || +m[1] !== +f.ch) return false; }
    if (f.app) { const m = d.p.match(/^app-([a-z])/); if (!m || m[1] !== f.app[0]) return false; }
    if (f.part) { if (!norm(d.part).replace(/[^a-z]/g, '').includes(f.part.replace(/[^a-z]/g, ''))) return false; }
    return true;
  }

  function candidateDocs(alt) {
    let set = null;
    for (const t of alt.terms) {
      const pl = IX.post.get(t);
      if (!pl) return new Set();
      const ks = new Set(pl.keys());
      set = set ? new Set([...set].filter(x => ks.has(x))) : ks;
    }
    return set || new Set();
  }

  function search(q, opts) {
    opts = opts || {};
    if (!buildIndex()) return { results: [], parsed: null };
    const parsed = parseQuery(q);
    if (!parsed.clauses.length && !Object.keys(parsed.filters).length) return { results: [], parsed };

    const scores = new Map();   // doc -> {score, matched:Set(clauseIdx), terms:Set}
    parsed.clauses.forEach((cl, ci) => {
      const best = new Map();
      for (const alt of cl.alts) {
        for (const i of candidateDocs(alt)) {
          if (cl.phrase && !IX.searchText[i].includes(cl.phrase)) continue;
          let s = 0;
          for (const t of alt.terms) s += termScore(t, i);
          s = s / Math.sqrt(alt.terms.length) * alt.w;
          const prev = best.get(i);
          if (!prev || s > prev.s) best.set(i, { s, terms: alt.terms, fuzzy: alt.fuzzy });
        }
      }
      for (const [i, b] of best) {
        let r = scores.get(i);
        if (!r) scores.set(i, (r = { score: 0, matched: new Set(), terms: new Set(), hl: { single: new Set(), phrases: new Map() } }));
        r.score += b.s;
        r.matched.add(ci);
        b.terms.forEach(t => r.terms.add(t));
        // highlight every strong alternative present in this doc (the word typed and its synonyms)
        for (const alt of cl.alts) {
          if (alt.w < 0.5 && alt !== cl.alts[0] && !alt.fuzzy) continue;
          if (!alt.terms.every(t => IX.post.get(t) && IX.post.get(t).has(i))) continue;
          if (cl.phrase || alt.terms.length > 1) r.hl.phrases.set(alt.terms.join('+'), alt.terms);
          else r.hl.single.add(alt.terms[0]);
        }
      }
    });

    // filter-only query: list everything in the filter
    if (!parsed.clauses.length) IX.docs.forEach((d, i) => scores.set(i, { score: 1 / (i + 1), matched: new Set(), terms: new Set(), hl: { single: new Set(), phrases: new Map() } }));

    const n = parsed.clauses.length;
    const out = [];
    for (const [i, r] of scores) {
      const d = IX.docs[i];
      if (!passesFilters(d, parsed.filters)) continue;
      if (parsed.exclude.some(t => IX.post.get(t) && IX.post.get(t).has(i))) continue;
      if (parsed.clauses.some((c, ci) => c.phrase && !r.matched.has(ci))) continue;
      let s = r.score;
      if (n > 1) {
        const cov = r.matched.size / n;
        s *= cov * cov;
        if (cov === 1) s *= 1.5 * proximityBonus(i, parsed, r);
      }
      if (!d.t) s *= 0.6;
      out.push({ i, d, score: s, terms: r.terms, hl: r.hl, full: r.matched.size === n });
    }
    out.sort((a, b) => b.score - a.score);
    return { results: out, parsed };
  }

  function proximityBonus(i, parsed, r) {
    const lists = [];
    for (const cl of parsed.clauses) {
      const ps = [];
      for (const alt of cl.alts) for (const t of alt.terms) if (r.terms.has(t)) (IX.bodyPos[i].get(t) || []).forEach(p => ps.push(p));
      if (!ps.length) return 1;
      lists.push(ps.sort((a, b) => a - b));
    }
    if (lists.length < 2) return 1;
    // smallest window containing one position from each list
    const ptr = lists.map(() => 0);
    let best = Infinity;
    for (;;) {
      let lo = Infinity, hi = -Infinity, loK = -1;
      lists.forEach((l, k) => { const v = l[ptr[k]]; if (v < lo) { lo = v; loK = k; } if (v > hi) hi = v; });
      best = Math.min(best, hi - lo);
      ptr[loK]++;
      if (ptr[loK] >= lists[loK].length) break;
    }
    const span = best - (lists.length - 1);
    return span <= 3 ? 1.35 : span <= 12 ? 1.15 : 1;
  }

  function suggest(parsed) {
    if (!parsed) return '';
    let changed = false;
    const words = norm(parsed.raw).split(/\s+/).map(w => {
      const t = stem(w.replace(/[^a-z0-9.\-/']/g, ''));
      if (!t || STOP.has(w) || IX.post.has(t) || /[:"-]/.test(w[0] || '')) return w;
      const f = fuzzyTerms(t);
      if (f.length) {
        const fix = IX.vocab.find(v => v === f[0][0]);
        if (fix) { changed = true; return surfaceForm(fix) || fix; }
      }
      return w;
    });
    return changed ? words.join(' ') : '';
  }

  function surfaceForm(stemmed) {
    // find a real word in the text that stems to this term, for "Did you mean"
    for (const t of IX.searchText) {
      const re = new RegExp(' (' + stemmed.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[a-z]{0,4}) ');
      const m = t.match(re);
      if (m && stem(m[1]) === stemmed) return m[1];
    }
    return null;
  }

  // ───────────────────────── snippets and highlighting ─────────────────────────
  function esc(s) { return s.replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }

  const TOKEN = /[A-Za-z0-9À-ɏ]+(?:[.'’\-/][A-Za-z0-9À-ɏ]+)*/g;

  function scanTokens(text) {
    const toks = [];
    let m;
    TOKEN.lastIndex = 0;
    while ((m = TOKEN.exec(text))) {
      const w = norm(m[0]).replace(/['’]s$/, '').replace(/['’]/g, '');
      toks.push({ s: m.index, e: m.index + m[0].length, w, st: stem(w), stop: STOP.has(w), hit: false });
    }
    return toks;
  }

  // Mark tokens that match the highlight spec: single terms, or whole phrases in order
  // (stop words in between are allowed, e.g. "drone as first responder").
  function markHits(toks, spec) {
    for (const t of toks) {
      if (spec.single.has(t.st) || spec.single.has(t.w) || spec.single.has(t.w.replace(/[.\-/]/g, ''))) t.hit = true;
      else if (/[.\-/]/.test(t.w) && t.w.split(/[.\-/]/).some(p => spec.single.has(stem(p)))) t.hit = true;
    }
    for (const ph of spec.phrases.values()) {
      for (let k = 0; k < toks.length; k++) {
        let j = k, n = 0;
        const span = [];
        while (j < toks.length && n < ph.length) {
          if (toks[j].st === ph[n] || toks[j].w === ph[n]) { span.push(j); n++; j++; }
          else if (toks[j].stop && n > 0) j++;
          else break;
        }
        if (n === ph.length) span.forEach(x => (toks[x].hit = true));
      }
    }
    return toks;
  }

  function markText(text, spec) {
    const toks = markHits(scanTokens(text), spec);
    let out = '', last = 0;
    for (const t of toks) {
      if (!t.hit) continue;
      out += esc(text.slice(last, t.s)) + '<mark>' + esc(text.slice(t.s, t.e)) + '</mark>';
      last = t.e;
    }
    return out + esc(text.slice(last));
  }

  function snippet(text, spec, maxWords) {
    const flat = text.replace(/\s*\n\s*/g, ' · ');
    const toks = markHits(scanTokens(flat), spec);
    if (!toks.length) return '';
    let bestStart = 0, bestScore = -1;
    for (let k = 0; k < toks.length; k++) {
      if (!toks[k].hit && k !== 0) continue;
      const start = Math.max(0, k - 6);
      const seen = new Set();
      let hits = 0;
      for (let j = start; j < Math.min(toks.length, start + maxWords); j++) if (toks[j].hit) { hits++; seen.add(toks[j].st); }
      const sc = seen.size * 10 + hits;
      if (sc > bestScore) { bestScore = sc; bestStart = start; }
    }
    const endTok = Math.min(toks.length, bestStart + maxWords) - 1;
    const a = toks[bestStart].s, b = toks[endTok].e;
    return (bestStart > 0 ? '… ' : '') + markText(flat.slice(a, b), spec) + (endTok < toks.length - 1 ? ' …' : '');
  }

  function specToParam(spec) {
    return Array.from(spec.single).concat(Array.from(spec.phrases.keys())).slice(0, 16).join(' ');
  }

  function paramToSpec(p) {
    const spec = { single: new Set(), phrases: new Map() };
    for (const part of p.split(/\s+/).filter(Boolean)) {
      if (part.includes('+')) spec.phrases.set(part, part.split('+'));
      else spec.single.add(part);
    }
    return spec;
  }

  function resultUrl(r, hl) {
    const q = hl ? '?hl=' + encodeURIComponent(hl) : '';
    return r.d.p + q + (r.d.a ? '#' + r.d.a : '');
  }

  function hlParam(r) { return specToParam(r.hl); }

  function crumbs(r) {
    const page = IX.pages.get(r.d.p);
    const parts = [page ? page.label : r.d.pt].concat(r.d.b || []);
    return parts.map(esc).join(' <span class="sr-sep">›</span> ');
  }

  // ───────────────────────── header dropdown ─────────────────────────
  function initHeader() {
    const box = document.querySelector('.hs');
    if (!box) return;
    const input = box.querySelector('.hs-input');
    const panel = box.querySelector('.hs-panel');
    const list = box.querySelector('.hs-list');
    const foot = box.querySelector('.hs-foot');
    const openBtn = box.querySelector('.hs-open');
    let active = -1, items = [], timer = null;

    function close() { panel.hidden = true; input.setAttribute('aria-expanded', 'false'); active = -1; }
    function setActive(k) {
      items.forEach((el, j) => el.classList.toggle('active', j === k));
      active = k;
      if (k >= 0 && items[k]) { input.setAttribute('aria-activedescendant', items[k].id); items[k].scrollIntoView({ block: 'nearest' }); }
    }
    function run() {
      const q = input.value.trim();
      if (!q) { close(); return; }
      const { results, parsed } = search(q);
      list.innerHTML = '';
      items = [];
      results.slice(0, 7).forEach((r, k) => {
        const li = document.createElement('li');
        li.id = 'hs-opt-' + k;
        li.setAttribute('role', 'option');
        li.className = 'hs-item';
        li.innerHTML = '<a href="' + esc(resultUrl(r, hlParam(r))) + '">' +
          '<span class="hs-crumb">' + crumbs(r) + '</span>' +
          '<span class="hs-title">' + markText(r.d.h, r.hl) + '</span>' +
          '<span class="hs-snip">' + snippet(r.d.t || r.d.h, r.hl, 18) + '</span></a>';
        li.addEventListener('mousemove', () => setActive(k));
        list.appendChild(li);
        items.push(li);
      });
      const all = 'search.html?q=' + encodeURIComponent(q);
      if (results.length) {
        foot.innerHTML = '<a href="' + all + '">See all ' + results.length + ' result' + (results.length === 1 ? '' : 's') +
          '</a><span class="hs-hint"><kbd>↑</kbd><kbd>↓</kbd> move <kbd>Enter</kbd> open</span>';
      } else {
        const s = suggest(parsed);
        foot.innerHTML = '<span class="hs-none">No matches.' + (s ? ' Try <a href="search.html?q=' + encodeURIComponent(s) + '">' + esc(s) + '</a>' : '') + '</span>';
      }
      panel.hidden = false;
      input.setAttribute('aria-expanded', 'true');
      setActive(results.length ? 0 : -1);
    }

    input.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(run, 60); });
    input.addEventListener('focus', () => { buildIndex(); if (input.value.trim()) run(); });
    input.addEventListener('keydown', e => {
      if (e.key === 'ArrowDown') { e.preventDefault(); if (items.length) setActive((active + 1) % items.length); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); if (items.length) setActive((active - 1 + items.length) % items.length); }
      else if (e.key === 'Enter') {
        e.preventDefault();
        const q = input.value.trim();
        if (active >= 0 && items[active]) location.href = items[active].querySelector('a').getAttribute('href');
        else if (q) location.href = 'search.html?q=' + encodeURIComponent(q);
      } else if (e.key === 'Escape') { close(); input.blur(); box.classList.remove('open'); }
    });
    document.addEventListener('click', e => { if (!box.contains(e.target)) { close(); box.classList.remove('open'); } });
    if (openBtn) openBtn.addEventListener('click', () => { box.classList.add('open'); input.focus(); });

    document.addEventListener('keydown', e => {
      const typing = /^(input|textarea|select)$/i.test(document.activeElement.tagName) || document.activeElement.isContentEditable;
      if ((e.key === '/' && !typing) || ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k')) {
        e.preventDefault();
        const sp = document.getElementById('sp-input');
        const target = sp || input;
        box.classList.add('open');
        target.focus();
        target.select();
      }
    });
  }

  // ───────────────────────── full results page ─────────────────────────
  function initResultsPage() {
    const input = document.getElementById('sp-input');
    if (!input) return;
    const facets = document.getElementById('sp-facets');
    const status = document.getElementById('sp-status');
    const list = document.getElementById('sp-results');
    const params = new URLSearchParams(location.search);
    input.value = params.get('q') || '';
    let part = params.get('in') || '';
    let shown = 25, timer = null;

    function render() {
      const q = input.value.trim();
      const url = new URL(location.href);
      if (q) url.searchParams.set('q', q); else url.searchParams.delete('q');
      if (part) url.searchParams.set('in', part); else url.searchParams.delete('in');
      history.replaceState(null, '', url);
      list.innerHTML = '';
      facets.innerHTML = '';
      if (!q) { status.textContent = 'Type to search ' + IX.N + ' sections across every chapter and appendix.'; return; }
      const t0 = performance.now();
      const { results, parsed } = search(q);
      const ms = Math.max(1, Math.round(performance.now() - t0));

      const counts = new Map();
      results.forEach(r => counts.set(r.d.part, (counts.get(r.d.part) || 0) + 1));
      const order = Array.from(new Set(IX.src.pages.map(p => p.part)));
      const chip = (label, val, n) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'sp-chip' + (part === val ? ' on' : '');
        b.innerHTML = esc(label) + ' <span>' + n + '</span>';
        b.addEventListener('click', () => { part = part === val ? '' : val; shown = 25; render(); });
        facets.appendChild(b);
      };
      if (results.length) {
        chip('All', '', results.length);
        order.forEach(p => counts.get(p) && chip(p, p, counts.get(p)));
      }
      const filtered = part ? results.filter(r => r.d.part === part) : results;
      if (!results.length) {
        const s = suggest(parsed);
        status.innerHTML = 'No sections match <strong>' + esc(q) + '</strong>.' +
          (s ? ' Did you mean <a href="search.html?q=' + encodeURIComponent(s) + '">' + esc(s) + '</a>?' : ' Try fewer words or check the tips below.');
        return;
      }
      const full = filtered.filter(r => r.full).length;
      status.textContent = filtered.length + ' section' + (filtered.length === 1 ? '' : 's') +
        (part ? ' in ' + part : '') + (parsed.clauses.length > 1 && full < filtered.length ? ' (' + full + ' match every word)' : '') +
        ' · ' + ms + ' ms';
      filtered.slice(0, shown).forEach(r => {
        const li = document.createElement('li');
        li.className = 'sp-item' + (r.full ? '' : ' partial');
        li.innerHTML = '<div class="sp-crumb">' + crumbs(r) + '</div>' +
          '<a class="sp-title" href="' + esc(resultUrl(r, hlParam(r))) + '">' + markText(r.d.h, r.hl) + '</a>' +
          '<p class="sp-snip">' + snippet(r.d.t || r.d.h, r.hl, 42) + '</p>';
        list.appendChild(li);
      });
      if (filtered.length > shown) {
        const li = document.createElement('li');
        li.className = 'sp-more';
        const b = document.createElement('button');
        b.type = 'button';
        b.textContent = 'Show ' + Math.min(25, filtered.length - shown) + ' more';
        b.addEventListener('click', () => { shown += 25; render(); });
        li.appendChild(b);
        list.appendChild(li);
      }
    }

    input.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(() => { shown = 25; render(); }, 80); });
    input.addEventListener('keydown', e => {
      if (e.key === 'Enter') { const a = list.querySelector('.sp-title'); if (a) location.href = a.getAttribute('href'); }
    });
    buildIndex();
    render();
    if (!input.value) input.focus();
  }

  // ───────────────────────── highlight on arrival ─────────────────────────
  function highlightOnArrival() {
    const hl = new URLSearchParams(location.search).get('hl');
    const root = document.querySelector('.content-wrapper');
    if (!hl || !root) return;
    const spec = paramToSpec(hl);
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode: n => n.parentElement.closest('script,style,.page-nav,mark') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT
    });
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    const marks = [];
    for (const node of nodes) {
      const text = node.nodeValue;
      const toks = markHits(scanTokens(text), spec).filter(t => t.hit);
      if (!toks.length) continue;
      const frag = document.createDocumentFragment();
      let last = 0;
      for (const t of toks) {
        frag.appendChild(document.createTextNode(text.slice(last, t.s)));
        const mk = document.createElement('mark');
        mk.className = 'search-hit';
        mk.textContent = text.slice(t.s, t.e);
        frag.appendChild(mk);
        marks.push(mk);
        last = t.e;
      }
      frag.appendChild(document.createTextNode(text.slice(last)));
      node.parentNode.replaceChild(frag, node);
    }
    if (!marks.length) return;

    const target = location.hash ? document.getElementById(decodeURIComponent(location.hash.slice(1))) : null;
    let cur = 0;
    if (target) {
      const after = marks.findIndex(mk => target.compareDocumentPosition(mk) & Node.DOCUMENT_POSITION_FOLLOWING);
      cur = after >= 0 ? after : 0;
    }
    const bar = document.createElement('div');
    bar.className = 'hl-bar';
    bar.innerHTML = '<span class="hl-count"></span><button type="button" data-d="-1" aria-label="Previous match">↑</button>' +
      '<button type="button" data-d="1" aria-label="Next match">↓</button><button type="button" class="hl-clear">Clear</button>';
    document.body.appendChild(bar);
    const count = bar.querySelector('.hl-count');
    function go(k, scroll) {
      marks.forEach(mk => mk.classList.remove('current'));
      cur = (k + marks.length) % marks.length;
      marks[cur].classList.add('current');
      count.textContent = (cur + 1) + ' of ' + marks.length + ' matches';
      if (scroll) marks[cur].scrollIntoView({ block: 'center', behavior: 'smooth' });
    }
    bar.addEventListener('click', e => {
      const d = e.target.getAttribute('data-d');
      if (d) go(cur + (+d), true);
      if (e.target.classList.contains('hl-clear')) {
        marks.forEach(mk => mk.replaceWith(document.createTextNode(mk.textContent)));
        bar.remove();
        const u = new URL(location.href); u.searchParams.delete('hl'); history.replaceState(null, '', u);
      }
    });
    go(cur, !target);
    if (target) requestAnimationFrame(() => target.scrollIntoView());
  }

  // expose for testing
  window.CRROSearch = { search, buildIndex, tokenize, stem, parseQuery, snippet, suggest, markText };

  function start() { initHeader(); initResultsPage(); highlightOnArrival(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
